module ranger_strength (\n  input clk,\n  input rst_n,\n  input start,\n  input [3:0] n,\n  input [3:0] k,\n  input [9:0] x,\n  input [9:0] arr_0, arr_1, arr_2, arr_3, arr_4, arr_5, arr_6, arr_7,\n  output reg [9:0] max_out,\n  output reg [9:0] min_out,\n  output reg done\n);\n\n  // State definitions\n  localparam [2:0] IDLE    = 3'd0;\n  localparam [2:0] SORT    = 3'd1;\n  localparam [2:0] XOR     = 3'd2;\n  localparam [2:0] CHECK_K = 3'd3;\n  localparam [2:0] FINISH  = 3'd4;\n  \n  reg [2:0] state, next_state;\n  reg [3:0] k_count;\n  reg [2:0] sort_step;\n  reg [9:0] arr [0:7];\n  reg [9:0] next_arr [0:7];\n  \n  integer i;\n  \n  // Combinational logic for array operations\n  always @(*) begin\n    for (i = 0; i < 8; i = i + 1) begin\n      next_arr[i] = arr[i];\n    end\n    \n    if (state == SORT) begin\n      case (sort_step)\n        3'd0: begin\n          if (n > 1 && arr[0] > arr[1]) begin\n            next_arr[0] = arr[1];\n            next_arr[1] = arr[0];\n          end\n        end\n        3'd2: begin\n          if (n > 3 && arr[2] > arr[3]) begin\n            next_arr[2] = arr[3];\n            next_arr[3] = arr[2];\n          end\n        end\n        3'd4: begin\n          if (n > 5 && arr[4] > arr[5]) begin\n            next_arr[4] = arr[5];\n            next_arr[5] = arr[4];\n          end\n        end\n        3'd6: begin\n          if (n > 7 && arr[6] > arr[7]) begin\n            next_arr[6] = arr[7];\n            next_arr[7] = arr[6];\n          end\n        end\n        3'd1: begin\n          if (n > 2 && arr[1] > arr[2]) begin\n            next_arr[1] = arr[2];\n            next_arr[2] = arr[1];\n          end\n        end\n        3'd3: begin\n          if (n > 4 && arr[3] > arr[4]) begin\n            next_arr[3] = arr[4];\n            next_arr[4] = arr[3];\n          end\n        end\n        3'd5: begin\n          if (n > 6 && arr[5] > arr[6]) begin\n            next_arr[5] = arr[6];\n            next_arr[6] = arr[5];\n          end\n        end\n        default: ;\n      endcase\n    end\n    else if (state == XOR) begin\n      for (i = 0; i < 8; i = i + 1) begin\n        if (i < n && (i % 2) == 0) begin\n          next_arr[i] = arr[i] ^ x;\n        end\n      end\n    end\n  end\n  \n  // Max/min calculation\n  reg [9:0] curr_max;\n  reg [9:0] curr_min;\n  always @(*) begin\n    curr_max = 10'd0;\n    curr_min = 10'h3FF;\n    for (i = 0; i < 8; i = i + 1) begin\n      if (i < n) begin\n        if (arr[i] > curr_max) curr_max = arr[i];\n        if (arr[i] < curr_min) curr_min = arr[i];\n      end\n    end\n  end\n  \n  // Sequential logic\n  always @(posedge clk or negedge rst_n) begin\n    if (!rst_n) begin\n      state <= IDLE;\n      done <= 1'b0;\n      k_count <= 4'd0;\n      sort_step <= 3'd0;\n      max_out <= 10'd0;\n      min_out <= 10'd0;\n      for (i = 0; i < 8; i = i + 1) begin\n        arr[i] <= 10'd0;\n      end\n    end\n    else begin\n      case (state)\n        IDLE: begin\n          done <= 1'b0;\n          if (start) begin\n            arr[0] <= arr_0;\n            arr[1] <= arr_1;\n            arr[2] <= arr_2;\n            arr[3] <= arr_3;\n            arr[4] <= arr_4;\n            arr[5] <= arr_5;\n            arr[6] <= arr_6;\n            arr[7] <= arr_7;\n            k_count <= k;\n            sort_step <= 3'd0;\n            state <= SORT;\n          end\n        end\n        \n        SORT: begin\n          for (i = 0; i < 8; i = i + 1) arr[i] <= next_arr[i];\n          sort_step <= sort_step + 3'd1;\n          if (sort_step == 3'd7) begin\n            state <= XOR;\n          end\n        end\n        \n        XOR: begin\n          for (i = 0; i < 8; i = i + 1) arr[i] <= next_arr[i];\n          state <= CHECK_K;\n        end\n        \n        CHECK_K: begin\n          if (k_count > 4'd1) begin\n            k_count <= k_count - 4'd1;\n            sort_step <= 3'd0;\n            state <= SORT;\n          end\n          else begin\n            state <= FINISH;\n          end\n        end\n        \n        FINISH: begin\n          max_out <= curr_max;\n          min_out <= curr_min;\n          done <= 1'b1;\n          state <= IDLE;\n        end\n        \n        default: state <= IDLE;\n      endcase\n    end\n  end\nendmodule